cli.help.full:
{bold}{cyan}╔═══════════════════════════════════════════════════════════════╗{/cyan}{/bold}
{bold}{cyan}║{/cyan}{/bold}  {bold}{white}mip v{{version}}{/white}{/bold} - {gray}npmがダメだから{/gray}                          {bold}{cyan}║{/cyan}{/bold}
{bold}{cyan}║{/cyan}{/bold}  {gray}プラグイン、セキュリティなど！{/gray}                                {bold}{cyan}║{/cyan}{/bold}
{bold}{cyan}╚═══════════════════════════════════════════════════════════════╝{/cyan}{/bold}

{bold}{white}メインコマンド:{/white}{/bold}
  {cyan}mip init{/cyan}                              {gray}新規プロジェクトを作成{/gray}
  {cyan}mip install{/cyan} {gray}[パッケージ]{/gray}               {gray}パッケージをインストール{/gray}
  {cyan}mip install -s{/cyan} {gray}[パッケージ]{/gray}            {gray}超高速インストール{/gray}
  {cyan}mip uninstall{/cyan} {gray}<パッケージ>{/gray}             {gray}パッケージを削除{/gray}
  {cyan}mip update{/cyan}                            {gray}全パッケージを更新{/gray}
  {cyan}mip list{/cyan}                              {gray}インストール済みパッケージを表示{/gray}

{bold}{white}情報:{/white}{/bold}
  {cyan}mip search{/cyan} {gray}<クエリ>{/gray}                    {gray}npmレジストリを検索{/gray}
  {cyan}mip info{/cyan} {gray}<パッケージ>{/gray}                  {gray}パッケージ詳細を表示{/gray}
  {cyan}mip outdated{/cyan}                           {gray}古いパッケージを表示{/gray}
  {cyan}mip why{/cyan} {gray}<パッケージ>{/gray}                   {gray}なぜこのパッケージがインストールされているか{/gray}

{bold}{white}セキュリティ:{/white}{/bold}
  {cyan}mip audit{/cyan}                             {gray}脆弱性をチェック{/gray}
  {cyan}mip doctor{/cyan}                            {gray}システム診断{/gray}

{bold}{white}開発:{/white}{/bold}
  {cyan}mip create{/cyan} {gray}<テンプレート> <名前>{/gray}       {gray}テンプレートから作成{/gray}
  {cyan}mip run{/cyan} {gray}<スクリプト>{/gray}                   {gray}npmスクリプトを実行{/gray}
  {cyan}mip exec{/cyan} {gray}<コマンド>{/gray}                    {gray}ローカルバイナリを実行{/gray}
  {cyan}mip link{/cyan}                              {gray}ローカルパッケージをリンク{/gray}

{bold}{white}エイリアス:{/white}{/bold}
  {cyan}mip alias set{/cyan} {gray}<名前> <コマンド>{/gray}        {gray}エイリアスを作成{/gray}
  {cyan}mip alias remove{/cyan} {gray}<名前>{/gray}               {gray}エイリアスを削除{/gray}
  {cyan}mip alias list{/cyan}                          {gray}全エイリアスを表示{/gray}
  {cyan}mip alias clear{/cyan}                         {gray}全エイリアスを削除{/gray}

{bold}{white}モノレポ:{/white}{/bold}
  {cyan}mip workspaces list{/cyan}                   {gray}Workspacesを一覧表示{/gray}
  {cyan}mip workspaces run{/cyan} {gray}<スクリプト>{/gray}        {gray}全てのWorkspaceでスクリプトを実行{/gray}

{bold}{white}メンテナンス:{/white}{/bold}
  {cyan}mip cache clean{/cyan}                       {gray}キャッシュをクリア{/gray}
  {cyan}mip cache size{/cyan}                        {gray}キャッシュサイズを表示{/gray}
  {cyan}mip ci{/cyan}                                {gray}CIインストール{/gray}

{bold}{white}例:{/white}{/bold}
  {gray}mip install -s express{/gray}                {gray}超高速インストール{/gray}
  {gray}mip install lodash --save-dev{/gray}
  {gray}mip create react my-app{/gray}
  {gray}mip why lodash{/gray}
  {gray}mip cache clean{/gray}
  {gray}mip doctor{/gray}
  {gray}mip alias set i install{/gray}               {gray}installのエイリアス{/gray}
  {gray}mip i express{/gray}                         {gray}エイリアスを使用{/gray}

{bold}{yellow}超高速モードの機能:{/yellow}{/bold}
  {green}✓{/green} {gray}並列ダウンロード{/gray}
  {green}✓{/green} {gray}ストリーム展開{/gray}
  {green}✓{/green} {gray}スマートキャッシング{/gray}
  {green}✓{/green} {gray}超高速再インストール{/gray}

commands.workspaces.default_help:
{bold}{white}Workspace コマンド:{/white}{/bold}

  {cyan}mip workspaces list{/cyan}                  {gray}全ての Workspace を一覧表示{/gray}
  {cyan}mip workspaces run{/cyan} {gray}<スクリプト>{/gray}      {gray}全ての Workspace でスクリプトを実行{/gray}
  {cyan}mip workspaces install{/cyan}               {gray}全ての Workspace に依存関係をインストール{/gray}
  {cyan}mip workspaces exec{/cyan} {gray}<コマンド>{/gray}       {gray}全ての Workspace でコマンドを実行{/gray}

{bold}{white}例:{/white}{/bold}
